// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "3mm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();
constexpr auto l_vec = noarr::vector<'l'>();
constexpr auto m_vec = noarr::vector<'m'>();

struct tuning {
	// Layout notes:
	//   In `scalar ^ X ^ Y`, the first applied vector (`X`) becomes the
	//   *innermost* / contiguous dimension, the later one (`Y`) the outer.
	//   We choose layouts so that the dimension used as the inner loop
	//   in each GEMM is contiguous in both input matrices.

	// A: i x k, inner dim: k  (good for summation over k)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // dims: 'i','k' ; 'k' contiguous

	// B: k x j, inner dim: k
	// Original: j_vec ^ k_vec  -> dims 'k','j', 'j' contiguous (bad for inner k loop)
	// Optimized: k_vec ^ j_vec -> dims 'j','k', 'k' contiguous (good for inner k loop)
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec);

	// C: j x m, inner dim: m   (good for summation over m)
	DEFINE_PROTO_STRUCT(c_layout, m_vec ^ j_vec); // dims: 'j','m' ; 'm' contiguous

	// D: m x l, inner dim: m
	// Original: l_vec ^ m_vec  -> dims 'm','l', 'l' contiguous (bad for inner m loop)
	// Optimized: m_vec ^ l_vec -> dims 'l','m', 'm' contiguous (good for inner m loop)
	DEFINE_PROTO_STRUCT(d_layout, m_vec ^ l_vec);

	// E: i x j, inner dim: j   (used with inner loop over j in last GEMM)
	DEFINE_PROTO_STRUCT(e_layout, j_vec ^ i_vec); // dims 'i','j' ; 'j' contiguous

	// F: j x l, inner dim: j
	// Original: l_vec ^ j_vec  -> dims 'j','l', 'l' contiguous (bad for inner j loop)
	// Optimized: j_vec ^ l_vec -> dims 'l','j', 'j' contiguous (good for inner j loop)
	DEFINE_PROTO_STRUCT(f_layout, j_vec ^ l_vec);

	// G: i x l, result, layout does not matter much for this kernel
	DEFINE_PROTO_STRUCT(g_layout, l_vec ^ i_vec);

} tuning;


// Array initialization
// --------------------
// Keep the original initialization formulas but:
//   * precompute 1 / (5 * N) for each N to avoid repeated divisions
//   * keep traversals purely in terms of Noarr traversers
void init_array(auto A, auto B, auto C, auto D) {
	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>();
	auto nl = D | get_length<'l'>();

	const auto inv_5ni = static_cast<num_t>(1) / static_cast<num_t>(5 * ni);
	const auto inv_5nj = static_cast<num_t>(1) / static_cast<num_t>(5 * nj);
	const auto inv_5nl = static_cast<num_t>(1) / static_cast<num_t>(5 * nl);
	const auto inv_5nk = static_cast<num_t>(1) / static_cast<num_t>(5 * nk);

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	traverser(A).template for_dims<'i', 'k'>([&](auto trav) {
		auto state = trav.state();
		auto [i, k] = get_indices<'i', 'k'>(state);

		const auto val = static_cast<num_t>((i * k + 1) % ni) * inv_5ni;
		A[trav] = val;
	});

	// B[k][j] = ((k * (j + 1) + 2) % nj) / (5 * nj)
	traverser(B).template for_dims<'k', 'j'>([&](auto trav) {
		auto state = trav.state();
		auto [k, j] = get_indices<'k', 'j'>(state);

		const auto val = static_cast<num_t>((k * (j + 1) + 2) % nj) * inv_5nj;
		B[trav] = val;
	});

	// C[j][m] = (j * (m + 3) % nl) / (5 * nl)
	// Note: the original benchmark intentionally uses `nl` here.
	traverser(C).template for_dims<'j', 'm'>([&](auto trav) {
		auto state = trav.state();
		auto [j, m] = get_indices<'j', 'm'>(state);

		const auto val = static_cast<num_t>((j * (m + 3) % nl)) * inv_5nl;
		C[trav] = val;
	});

	// D[m][l] = ((m * (l + 2) + 2) % nk) / (5 * nk)
	traverser(D).template for_dims<'m', 'l'>([&](auto trav) {
		auto state = trav.state();
		auto [m, l] = get_indices<'m', 'l'>(state);

		const auto val = static_cast<num_t>(((m * (l + 2) + 2) % nk)) * inv_5nk;
		D[trav] = val;
	});
}


// computation kernel
// ------------------
// Optimizations:
//   * We keep the original mathematical loop structure (i,j,k / j,l,m / i,l,j)
//     to preserve the exact per-element accumulation order.
//   * For each output element we accumulate into a scalar `sum` in a register,
//     and write it back to memory once at the end. This avoids repeated reads
//     and writes of partial sums.
//   * Data layouts (see `tuning` above) are chosen so that inner loop dimensions
//     are contiguous in both multiplicands, improving cache and vectorization.
//   * All traversals remain expressed via Noarr traversers and for_dims.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop

	// ----------------------------------
	// E := A * B
	// ----------------------------------
	traverser(E, A, B).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// acc for fixed (i, j)
		num_t sum = static_cast<num_t>(0);

		// accumulate over k
		trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
			// Thanks to tuned layouts:
			//   A: contiguous in 'k'
			//   B: contiguous in 'k'
			// This inner loop sees unit-stride accesses for both A and B.
			sum += A[trav_ijk] * B[trav_ijk];
		});

		// write the final value once
		E[trav_ij] = sum;
	});

	// ----------------------------------
	// F := C * D
	// ----------------------------------
	traverser(F, C, D).template for_dims<'j', 'l'>([&](auto trav_jl) {
		num_t sum = static_cast<num_t>(0);

		// accumulate over m
		trav_jl.template for_dims<'m'>([&](auto trav_jlm) {
			// Tuned layouts:
			//   C: contiguous in 'm'
			//   D: contiguous in 'm'
			sum += C[trav_jlm] * D[trav_jlm];
		});

		F[trav_jl] = sum;
	});

	// ----------------------------------
	// G := E * F
	// ----------------------------------
	traverser(G, E, F).template for_dims<'i', 'l'>([&](auto trav_il) {
		num_t sum = static_cast<num_t>(0);

		// accumulate over j
		trav_il.template for_dims<'j'>([&](auto trav_ilj) {
			// Tuned layouts:
			//   E: contiguous in 'j'
			//   F: contiguous in 'j'
			sum += E[trav_ilj] * F[trav_ilj];
		});

		G[trav_il] = sum;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

	// allocate data
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto D = noarr::bag(noarr::scalar<num_t>() ^ tuning.d_layout ^ set_lengths);
	auto E = noarr::bag(noarr::scalar<num_t>() ^ tuning.e_layout ^ set_lengths);
	auto F = noarr::bag(noarr::scalar<num_t>() ^ tuning.f_layout ^ set_lengths);
	auto G = noarr::bag(noarr::scalar<num_t>() ^ tuning.g_layout ^ set_lengths);

	// initialize arrays
	init_array(A.get_ref(), B.get_ref(), C.get_ref(), D.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_3mm(E.get_ref(), A.get_ref(), B.get_ref(),
	           F.get_ref(), C.get_ref(), D.get_ref(), G.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, G.get_ref() ^ noarr::hoist<'i'>());
	}

	// print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
