	// A: i x k
	// B: k x j
	// C: j x m
	// D: m x l
	using namespace noarr;

	auto ni = A | get_length<'i'>();
	auto nk = A | get_length<'k'>();
	auto nj = B | get_length<'j'>();
	auto nm = C | get_length<'m'>();
	auto nl = D | get_length<'l'>();

	const num_t inv_5_ni = num_t(1) / (num_t(5) * num_t(ni));
	const num_t inv_5_nj = num_t(1) / (num_t(5) * num_t(nj));
	const num_t inv_5_nl = num_t(1) / (num_t(5) * num_t(nl));
	const num_t inv_5_nk = num_t(1) / (num_t(5) * num_t(nk));

	// A[i][k] = ((i * k + 1) % ni) / (5 * ni)
	// Layout of A is i (outer) x k (inner), so iterating 'i','k' writes contiguously.
	traverser(A).template for_dims<'i', 'k'>([=](auto trav) {
		auto state = trav.state();
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = num_t((i * k + 1) % ni) * inv_5_ni;
	});

