[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop

	// ---------------------------------------------------------------------
	// 0) Initialize result matrices to zero
	// ---------------------------------------------------------------------
	traverser(E).for_each([&](auto s) {
		E[s] = num_t(0.0);
	});
	traverser(F).for_each([&](auto s) {
		F[s] = num_t(0.0);
	});
	traverser(G).for_each([&](auto s) {
		G[s] = num_t(0.0);
	});

	// ---------------------------------------------------------------------
	// 1) E := A * B
	//
	// We exploit the layouts:
	//   A: i (outer) x k (inner)
	//   B: k (outer) x j (inner)
	//   E: i (outer) x j (inner)
	//
	// Loop order: i -> k -> j
	//   - For fixed (i,k) we load A(i,k) once into a scalar a_ik.
	//   - Inner loop over j walks B(k,j) and E(i,j) contiguously.
	// ---------------------------------------------------------------------
	auto trav_EAB = traverser(E, A, B);

	trav_EAB.template for_dims<'i'>([&](auto trav_i) {
		// 'trav_i' has 'i' fixed.

		// Middle loop over k: reuse A(i,k) across all j.
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			const num_t a_ik = A[trav_ik];

			// Inner loop over j: contiguous in both B(k,j) and E(i,j).
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				E[trav_ikj] += a_ik * B[trav_ikj];
			});
		});
	});

	// ---------------------------------------------------------------------
	// 2) F := C * D
	//
	// Layouts:
	//   C: j (outer) x m (inner)
	//   D: m (outer) x l (inner)
	//   F: j (outer) x l (inner)
	//
	// Loop order: j -> m -> l
	//   - For fixed (j,m) we load C(j,m) once into scalar c_jm.
	//   - Inner loop over l walks D(m,l) and F(j,l) contiguously.
	// ---------------------------------------------------------------------
	auto trav_FCD = traverser(F, C, D);

	trav_FCD.template for_dims<'j'>([&](auto trav_j) {
		// 'trav_j' has 'j' fixed.

		// Middle loop over m: reuse C(j,m) across all l.
		trav_j.template for_dims<'m'>([&](auto trav_jm) {
			const num_t c_jm = C[trav_jm];

			// Inner loop over l: contiguous in D(m,l) and F(j,l).
			trav_jm.template for_dims<'l'>([&](auto trav_jml) {
				F[trav_jml] += c_jm * D[trav_jml];
			});
		});
	});

	// ---------------------------------------------------------------------
	// 3) G := E * F
	//
	// Layouts:
	//   E: i (outer) x j (inner)
	//   F: j (outer) x l (inner)
	//   G: i (outer) x l (inner)
	//
	// Loop order: i -> j -> l
	//   - For fixed (i,j) we load E(i,j) once into scalar e_ij.
	//   - Inner loop over l walks F(j,l) and G(i,l) contiguously.
	// ---------------------------------------------------------------------
	auto trav_GEF = traverser(G, E, F);

	trav_GEF.template for_dims<'i'>([&](auto trav_i) {
		// 'trav_i' has 'i' fixed.

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			const num_t e_ij = E[trav_ij];

			// Inner loop over l: contiguous in F(j,l) and G(i,l).
			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				G[trav_ijl] += e_ij * F[trav_ijl];
			});
		});
	});

	#pragma endscop
}

