// computation kernel
// The kernel is written to:
//   * access all matrices in cache-friendly, contiguous orders
//   * exploit parallelism across rows using OpenMP (if enabled)
//   * keep all loop nests expressed via Noarr traversers
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	using namespace noarr;

	// Problem sizes used for simple OpenMP tuning
	const std::size_t ni = E | get_length<'i'>();
	const std::size_t nj = F | get_length<'j'>();

	// Minimal number of rows to justify spawning parallel regions.
	// This constant can be tuned for specific hardware.
	constexpr std::size_t min_parallel_rows = 32;

	#pragma scop
	// ------------------------------------------------------------------
	// 0) Explicitly zero all outputs once.
	//    This gives very simple, vectorizable loops and allows us
	//    to use accumulation-friendly orders for the multiplications.
	// ------------------------------------------------------------------
	traverser(E).for_each([&](auto s) { E[s] = (num_t)0.0; });
	traverser(F).for_each([&](auto s) { F[s] = (num_t)0.0; });
	traverser(G).for_each([&](auto s) { G[s] = (num_t)0.0; });

	// ------------------------------------------------------------------
	// 1) E := A * B
	//
	//    Shapes:
	//      A: i x k  (contiguous in k)
	//      B: k x j  (contiguous in j)
	//      E: i x j  (contiguous in j)
	//
	//    Loop order used:
	//      i (outer, parallel)  ->  k  ->  j (innermost)
	//
	//    For fixed (i, k) we:
	//      * load a_ik once
	//      * walk j contiguously in both B[k,j] and E[i,j]
	//
	//    This gives good spatial locality for A's rows, B's rows and
	//    E's rows, and is friendly to vectorization.
	// ------------------------------------------------------------------
	auto trav_EAB = traverser(E, A, B).order(hoist<'i'>());

	#pragma omp parallel for if(ni >= min_parallel_rows)
	for (auto trav_i : trav_EAB) {
		// trav_i has 'i' fixed; remaining logical dimensions are 'k' and 'j'.
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			const num_t a_ik = A[trav_ik];

			// Skip the inner loop entirely when the contribution is zero.
			// All inputs are finite and generated analytically, so this is
			// safe and does not change the mathematical result.
			if (a_ik == num_t(0.0))
				return;

			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				E[trav_ikj] += a_ik * B[trav_ikj];
			});
		});
	}

	// ------------------------------------------------------------------
	// 2) F := C * D
	//
	//    Shapes:
	//      C: j x m  (contiguous in m)
	//      D: m x l  (contiguous in l)
	//      F: j x l  (contiguous in l)
	//
	//    Loop order used:
	//      j (outer, parallel)  ->  m  ->  l (innermost)
	//
	//    For fixed (j, m) we:
	//      * load c_jm once
	//      * walk l contiguously in both D[m,l] and F[j,l]
	// ------------------------------------------------------------------
	auto trav_FCD = traverser(F, C, D).order(hoist<'j'>());

	#pragma omp parallel for if(nj >= min_parallel_rows)
	for (auto trav_j : trav_FCD) {
		// trav_j has 'j' fixed; remaining logical dimensions are 'm' and 'l'.
		trav_j.template for_dims<'m'>([&](auto trav_jm) {
			const num_t c_jm = C[trav_jm];

			if (c_jm == num_t(0.0))
				return;

			trav_jm.template for_dims<'l'>([&](auto trav_jml) {
				F[trav_jml] += c_jm * D[trav_jml];
			});
		});
	}

	// ------------------------------------------------------------------
	// 3) G := E * F
	//
	//    Shapes:
	//      E: i x j  (contiguous in j)
	//      F: j x l  (contiguous in l)
	//      G: i x l  (contiguous in l)
	//
	//    We choose the order:
	//      i (outer, parallel)  ->  j  ->  l (innermost)
	//
	//    For fixed (i, j) we:
	//      * load e_ij once
	//      * walk l contiguously in both F[j,l] and G[i,l]
	//
	//    This makes use of row-wise locality in F and G, while still
	//    preserving the exact arithmetic result:
	//      G[i,l] = sum_j E[i,j] * F[j,l]
	// ------------------------------------------------------------------
	auto trav_GEF = traverser(G, E, F).order(hoist<'i'>());

	#pragma omp parallel for if(ni >= min_parallel_rows)
	for (auto trav_i : trav_GEF) {
		// trav_i has 'i' fixed; remaining logical dimensions are 'j' and 'l'.
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			const num_t e_ij = E[trav_ij];

			if (e_ij == num_t(0.0))
				return;

			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				G[trav_ijl] += e_ij * F[trav_ijl];
			});
		});
	}
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;
	std::size_t nm = NM;

	// set lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl) ^
		noarr::set_length<'m'>(nm);

