// inner (contiguous) dimension of the relevant matrices:
//
//   E = A * B :  loops (i, k, j)
//       - A(i,k)  : k is inner -> contiguous across k in the k-loop
//       - B(k,j)  : j is inner -> contiguous across j in the j-loop
//       - E(i,j)  : j is inner -> contiguous across j in the j-loop
//
//   F = C * D :  loops (j, m, l)
//       - C(j,m)  : m is inner -> contiguous across m in the m-loop
//       - D(m,l)  : l is inner -> contiguous across l in the l-loop
//       - F(j,l)  : l is inner -> contiguous across l in the l-loop
//
//   G = E * F :  loops (i, j, l)
//       - E(i,j)  : j is inner -> contiguous across j in the j-loop
//       - F(j,l)  : l is inner -> contiguous across l in the l-loop
//       - G(i,l)  : l is inner -> contiguous across l in the l-loop
