//    thus preserving the original access patterns while reducing memory
//    traffic on the result matrices.
[[gnu::flatten, gnu::noinline]]
void kernel_3mm(auto E, auto A, auto B, auto F, auto C, auto D, auto G) {
	// E: i x j  = A (i x k) * B (k x j)
	// F: j x l  = C (j x m) * D (m x l)
	// G: i x l  = E (i x j) * F (j x l)
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// E := A * B
	// ------------------------------------------------------------------
	//
	// Original semantics:
	//   for i
	//     for j
	//       E[i,j] = 0;
	//       for k
	//         E[i,j] += A[i,k] * B[k,j];
	//
	// New version keeps the same iteration order, but uses a scalar
	// accumulator `sum` to avoid repeatedly reading/writing E[i,j].
	traverser(E, A, B).template for_dims<'i'>([&](auto trav_i) {
		// trav_i: 'i' fixed, remaining dims: 'j', 'k'
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// trav_ij: 'i' and 'j' fixed, remaining dim: 'k'
			num_t sum = num_t(0);

			trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
				sum += A[trav_ijk] * B[trav_ijk];
			});

			E[trav_ij] = sum;
		});
	});

	// ------------------------------------------------------------------
	// F := C * D
	// ------------------------------------------------------------------
	//
	// Original semantics:
	//   for j
	//     for l
	//       F[j,l] = 0;
	//       for m
	//         F[j,l] += C[j,m] * D[m,l];
	//
	// Again we keep the same logical order but use a scalar accumulator.
	traverser(F, C, D).template for_dims<'j'>([&](auto trav_j) {
		// trav_j: 'j' fixed, remaining dims: 'l', 'm'
		trav_j.template for_dims<'l'>([&](auto trav_jl) {
			// trav_jl: 'j' and 'l' fixed, remaining dim: 'm'
			num_t sum = num_t(0);

			trav_jl.template for_dims<'m'>([&](auto trav_jlm) {
				sum += C[trav_jlm] * D[trav_jlm];
			});

			F[trav_jl] = sum;
		});
	});

	// ------------------------------------------------------------------
	// G := E * F
	// ------------------------------------------------------------------
	//
	// Original semantics:
	//   for i
	//     for l
	//       G[i,l] = 0;
	//       for j
	//         G[i,l] += E[i,j] * F[j,l];
	//
	// We mirror this structure but again use a scalar accumulator for G.
	traverser(G, E, F).template for_dims<'i'>([&](auto trav_i) {
		// trav_i: 'i' fixed, remaining dims: 'l', 'j'
		trav_i.template for_dims<'l'>([&](auto trav_il) {
			// trav_il: 'i' and 'l' fixed, remaining dim: 'j'
			num_t sum = num_t(0);

			trav_il.template for_dims<'j'>([&](auto trav_ilj) {
				sum += E[trav_ilj] * F[trav_ilj];
			});

			G[trav_il] = sum;
		});
	});

	#pragma endscop
}

